            "default": "ripe"
          },
          {
            "name": "tree_id",
            "type": "entity_ref",
            "default": "tree-1"
          }
        ]
      }
    ],
    "entities": [
      {
        "id": "ava",
        "label": "Ava",
        "categories": [
          "worker"
        ],
        "components": {
          "worker": {
            "stamina": 10
          }
        }
      },
      {
        "id": "tree-1",
        "label": "Apple tree",
        "categories": [
          "tree"
        ],
        "components": {}
      },
      {
