            "tree_id": "tree-1"
          }
        }
      }
    ],
    "actions": [
      {
        "kind": "pick",
        "description": "Pick one represented fruit.",
        "fields": [
          {
            "name": "fruit",
            "type": "entity_ref"
          }
        ]
      }
    ],
    "presentation": {
      "assets": {
        "worker": {
          "kind": "emoji",
          "value": "\ud83e\uddd1\u200d\ud83c\udf3e"
        },
        "fruit": {
