        "fruit": "fruit"
      },
      "station_roles": {
        "tree": "source"
      }
    }
  }
}"}, {"role": "assistant", "content": "{"schema_version": "world-substrate-authoring-bundle/v0", "world": {"id": "pencil-supply-chain", "label": "Pencil Supply Chain", "summary": "Specialists keep making, moving, and selling pencils from raw materials to customers.", "location": "oregon", "content_version": 1}, "components": [{"name": "place_info", "fields": [{"name": "kind", "type": "string", "default": "workplace"}]}, {"name": "business", "fields": [{"name": "role", "type": "string", "default": "producer"}, {"name": "cash", "type": "number", "default": 1000}, {"name": "logs", "type": "integer", "default": 0}, {"name": "slats", "type": "integer", "default": 0}, {"name": "graphite", "type": "integer", "default": 0}, {"name": "clay", "type": "integer", "default": 0}, {"name": "leads", "type": "integer", "default": 0}, {"name": "paint", "type": "integer", "default": 0}, {"name": "erasers", "type": "integer", "default": 0}, {"name": "ferrules", "type": "integer", "default": 0}, {"name": "pencils", "type": "integer", "default": 0}, {"name": "boxes", "type": "integer", "default": 0}, {"name": "packed_pencils", "type": "integer", "default": 0}, {"name": "price", "type": "number", "default": 1}, {"name": "rounds_left", "type": "integer", "default": 0}, {"name": "waiting_orders", "type": "integer", "default": 3}]}], "entities": [{"id": "oregon", "label": "Oregon", "categories": ["place"], "components": {"place_info": {"kind": "region"}}}, {"id": "sri-lanka", "label": "Sri Lanka", "categories": ["place"], "components": {"place_info": {"kind": "region"}}}, {"id": "pennsylvania", "label": "Pennsylvania", "categories": ["place"], "components": {"place_info": {"kind": "region"}}}, {"id": "shops-countrywide", "label": "Shops across the country", "categories": ["place"], "components": {"place_info": {"kind": "region"}}}, {"id": "loggers", "label": "Oregon loggers", "categories": ["actor", "producer"], "location": "oregon", "components": {"business": {"role": "cut cedar", "cash": 1